import type { Article } from "../articles";

export const costSectionsA: Article["sections"] = [
  {
    heading: "How much do GLP-1 weight loss drugs cost in 2026?",
    body: `<p>In 2026, GLP-1 weight loss drugs cost anywhere from $50 a month (the Medicare GLP-1 Bridge copay) to roughly $1,060-$1,350 a month at full list price, and most adults paying cash for brand-name Wegovy, Zepbound, the Wegovy pill or Foundayo pay between $149 and $449 a month as of October 2026. How you pay now matters more than which drug you take.</p>
<p>A year ago the numbers looked very different. Before the November 2025 deal between the White House, Eli Lilly and Novo Nordisk, the White House described Wegovy as costing about $1,350 a month, according to <a href="https://www.ajmc.com/view/trump-announces-deals-with-eli-lilly-novo-nordisk-for-lower-weight-loss-drug-prices" target="_blank" rel="noopener">AJMC's report on the deal</a>. As of October 2026, the <a href="https://www.novocare.com/content/dam/novonordisk/novocare/redesign/pdf/Wegovy_Price_Guide.pdf" target="_blank" rel="noopener">NovoCare Wegovy price guide</a> lists the Wegovy pen at $349 a month for self-pay patients at every dose from 0.25 mg to 2.4 mg, and <a href="https://www.lilly.com/lillydirect/zepbound" target="_blank" rel="noopener">LillyDirect</a> sells Zepbound starting at $299 a month.</p>
<p>Demand keeps climbing even though cost still bites. <a href="https://news.gallup.com/poll/712157/glp-usage-reaches-new-high.aspx" target="_blank" rel="noopener">Gallup reported in July 2026</a> that 11% of US adults currently take a GLP-1 for weight loss, up from 3% in 2024. In the <a href="https://www.kff.org/public-opinion/kff-health-tracking-poll-prescription-drug-costs-views-on-trump-administration-actions-and-glp-1-use/" target="_blank" rel="noopener">KFF Health Tracking Poll</a> fielded in late October and early November 2025, 56% of current or recent users said the drugs were difficult to afford, and 14% said they had stopped taking them because of cost.</p>
<h3>Every main way to pay, side by side</h3>
<table>
<thead><tr><th>Way to pay</th><th>Typical monthly cost (as of October 2026)</th><th>Who qualifies</th><th>Source</th></tr></thead>
<tbody>
<tr><td>Full list price</td><td>Wegovy about $1,349; Zepbound about $1,060-$1,090</td><td>The starting "sticker" price insurers negotiate from; few people pay it in full</td><td><a href="https://www.healthsystemtracker.org/brief/how-trumprx-brand-name-drug-prices-compare-to-other-countries/" target="_blank" rel="noopener">Peterson-KFF</a>, <a href="https://www.ajmc.com/view/trumprx-launch-brings-savings-and-uncertainty" target="_blank" rel="noopener">AJMC</a></td></tr>
<tr><td>Brand-name self-pay injection (NovoCare, LillyDirect, TrumpRx)</td><td>Wegovy pen $199 intro, then $349; Wegovy HD $399; Zepbound $299-$449</td><td>Adults with a valid prescription paying cash</td><td><a href="https://www.novocare.com/content/dam/novonordisk/novocare/redesign/pdf/Wegovy_Price_Guide.pdf" target="_blank" rel="noopener">NovoCare</a>, <a href="https://www.lilly.com/lillydirect/zepbound" target="_blank" rel="noopener">Lilly</a></td></tr>
<tr><td>Brand-name self-pay pill</td><td>Wegovy pill and Foundayo $149-$299 (Foundayo up to $349 if refilled late)</td><td>Adults with a valid prescription paying cash</td><td><a href="https://www.cnn.com/2026/01/06/health/wegovy-pill-weight-loss-explained" target="_blank" rel="noopener">CNN</a>, <a href="https://www.lilly.com/lillydirect/foundayo" target="_blank" rel="noopener">Lilly</a></td></tr>
<tr><td>Medicare GLP-1 Bridge</td><td>$50 per one-month supply</td><td>Part D or Medicare Advantage drug plan enrollees who meet BMI and clinical criteria</td><td><a href="https://www.cms.gov/medicare/coverage/prescription-drug-coverage/medicare-glp-1-bridge" target="_blank" rel="noopener">CMS</a></td></tr>
<tr><td>Commercial insurance plus manufacturer savings card</td><td>As little as $25 when the plan covers the drug</td><td>Commercially insured only; no Medicare or Medicaid</td><td><a href="https://www.novocare.com/patient/medicines/wegovy/savings-offer.html" target="_blank" rel="noopener">NovoCare</a></td></tr>
<tr><td>Medicaid</td><td>Low state-set copays where obesity coverage exists</td><td>Enrollees in one of the 13 states KFF counted as covering obesity GLP-1s (January 2026)</td><td><a href="https://www.kff.org/medicaid/medicaid-coverage-of-and-spending-on-glp-1s/" target="_blank" rel="noopener">KFF</a></td></tr>
<tr><td>Compounded semaglutide through telehealth</td><td>Advertised from around $99-$199, rising with dose, often plus fees</td><td>Not FDA-approved; legal limits have tightened since 2025</td><td><a href="https://health.usnews.com/best-diet/medication/hims-&-hers" target="_blank" rel="noopener">US News</a>, <a href="https://www.fda.gov/news-events/press-announcements/fda-warns-30-telehealth-companies-against-illegal-marketing-compounded-glp-1s" target="_blank" rel="noopener">FDA</a></td></tr>
</tbody>
</table>
<h3>What the table means for your budget</h3>
<p>The cheapest entry points are now pills. The 1.5 mg Wegovy pill and the 0.8 mg Foundayo starting dose each cost $149 a month self-pay as of October 2026, according to <a href="https://www.cnn.com/2026/01/06/health/wegovy-pill-weight-loss-explained" target="_blank" rel="noopener">CNN</a> and <a href="https://www.lilly.com/lillydirect/foundayo" target="_blank" rel="noopener">LillyDirect</a>. Starting prices are not what you will pay for long, though, because most people step up to a maintenance dose. At maintenance, pills run $299, the Wegovy pen $349, Wegovy HD $399 and Zepbound $449 when refilled on time, based on the <a href="https://www.novocare.com/content/dam/novonordisk/novocare/redesign/pdf/Wegovy_Price_Guide.pdf" target="_blank" rel="noopener">NovoCare price guide</a> and <a href="https://www.lilly.com/lillydirect/zepbound" target="_blank" rel="noopener">LillyDirect</a>. Over 12 months at maintenance, that works out to about $3,588 for a $299 pill, $4,188 for the Wegovy pen and $5,388 for Zepbound.</p>
<p>Compounded versions used to be the obvious budget pick. With brand-name self-pay prices now starting at $149, the gap has narrowed a lot, and compounded drugs are not FDA-approved, which means the <a href="https://www.fda.gov/news-events/press-announcements/fda-warns-30-telehealth-companies-against-illegal-marketing-compounded-glp-1s" target="_blank" rel="noopener">FDA</a> does not review them for safety, effectiveness or quality before they are sold. Our guide to <a href="/articles/compounded-semaglutide-vs-brand-name">compounded semaglutide vs brand-name</a> walks through the tradeoffs, and our <a href="/cheapest-glp1">cheapest GLP-1 options</a> page tracks current prices.</p>
<p>All prices in this guide were checked as of October 2026 against the sources linked in each section. Manufacturers change self-pay prices and introductory offers often, so confirm the current price on NovoCare, LillyDirect or TrumpRx before you fill a prescription.</p>`,
  },
  {
    heading: "Why did GLP-1 prices change so much in 2026?",
    body: `<p>GLP-1 prices changed so much in 2026 because of a chain of federal deals and new launches: the November 6, 2025 agreements between President Trump, Eli Lilly and Novo Nordisk, the TrumpRx.gov launch in February 2026, FDA approval of two GLP-1 pills, the $50 Medicare GLP-1 Bridge that started July 1, 2026, and a Medicare negotiated price for semaglutide that takes effect in 2027.</p>
<h3>The November 2025 deal set the tone</h3>
<p>On November 6, 2025, President Trump announced agreements with Eli Lilly and Novo Nordisk to lower GLP-1 prices for Medicare, Medicaid and cash-paying patients, as <a href="https://www.cnbc.com/2025/11/06/obesity-drug-prices-trump-deals-eli-lilly-novo-nordisk.html" target="_blank" rel="noopener">CNBC reported</a>. Under the deal, Medicare and participating Medicaid programs pay $245 a month for covered GLP-1s, and Medicare patients pay no more than $50, according to <a href="https://www.ajmc.com/view/trump-announces-deals-with-eli-lilly-novo-nordisk-for-lower-weight-loss-drug-prices" target="_blank" rel="noopener">AJMC</a> and <a href="https://www.healthcaredive.com/news/lilly-novo-trump-obesity-drug-pricing-deal-zepbound-wegovy/804937/" target="_blank" rel="noopener">Healthcare Dive</a>. Officials said cash prices for injectables would start around $350 a month and fall over roughly two years. AJMC reported an endpoint of about $245, while <a href="https://www.forbes.com/sites/tylerroush/2025/12/01/eli-lilly-lowers-weight-loss-drug-zepbound-prices-after-trump-deal/" target="_blank" rel="noopener">Forbes</a> reported $250.</p>
<p>The manufacturers moved quickly. Novo Nordisk cut its standard Wegovy and Ozempic self-pay price from $499 to $349 a month on November 17, 2025 and added a $199 introductory price, per <a href="https://www.prnewswire.com/news-releases/novo-nordisk-launches-introductory-self-pay-offer-for-wegovy-and-ozempic-for-199-per-month-302617100.html" target="_blank" rel="noopener">Novo Nordisk's announcement</a>. Lilly followed on December 1, 2025, cutting Zepbound vial prices to $299-$449 a month from $349-$499, as <a href="https://www.cnbc.com/2025/12/01/eli-lilly-prices-zepbound-weight-loss-drug-vials.html" target="_blank" rel="noopener">CNBC reported</a>.</p>
<h3>Timeline of the changes that affect your price</h3>
<table>
<thead><tr><th>Date</th><th>What happened</th><th>Why it matters to you</th></tr></thead>
<tbody>
<tr><td>Nov 6, 2025</td><td>Trump, Lilly and Novo announce GLP-1 pricing deal (<a href="https://www.cnbc.com/2025/11/06/obesity-drug-prices-trump-deals-eli-lilly-novo-nordisk.html" target="_blank" rel="noopener">CNBC</a>)</td><td>Set the $245 government price and $50 Medicare copay target</td></tr>
<tr><td>Nov 17, 2025</td><td>Novo cuts Wegovy self-pay to $349 and adds $199 intro (<a href="https://www.prnewswire.com/news-releases/novo-nordisk-launches-introductory-self-pay-offer-for-wegovy-and-ozempic-for-199-per-month-302617100.html" target="_blank" rel="noopener">Novo</a>)</td><td>Cash price of the Wegovy pen fell by $150 a month</td></tr>
<tr><td>Nov 25, 2025</td><td>CMS announces $274 Medicare negotiated price for semaglutide, effective Jan 1, 2027 (<a href="https://www.biopharmadive.com/news/medicare-price-negotiation-wegovy-ozempic-trelegy-2027/806526/" target="_blank" rel="noopener">BioPharma Dive</a>)</td><td>Lowers what Medicare pays starting 2027</td></tr>
<tr><td>Dec 1, 2025</td><td>Lilly cuts Zepbound vials to $299-$449 (<a href="https://www.cnbc.com/2025/12/01/eli-lilly-prices-zepbound-weight-loss-drug-vials.html" target="_blank" rel="noopener">CNBC</a>)</td><td>Cheaper cash Zepbound</td></tr>
<tr><td>Dec 22, 2025</td><td>FDA approves the Wegovy pill (<a href="https://www.cnn.com/2025/12/22/health/wegovy-pill-glp1-weight-loss-drugs" target="_blank" rel="noopener">CNN</a>)</td><td>First oral GLP-1 for weight loss</td></tr>
<tr><td>Late Dec 2025</td><td>CMS announces the BALANCE Model (<a href="https://www.aha.org/news/headline/2025-12-29-cms-proposes-new-drug-pricing-model-expand-glp-1-access-those-medicare-part-d-and-medicaid" target="_blank" rel="noopener">AHA</a>)</td><td>Framework for Medicaid and Part D coverage deals</td></tr>
<tr><td>Jan 1, 2026</td><td>California, New Hampshire, Pennsylvania and South Carolina Medicaid end obesity GLP-1 coverage (<a href="https://stateline.org/2025/11/28/states-retreat-from-covering-drugs-for-weight-loss/" target="_blank" rel="noopener">Stateline</a>)</td><td>Fewer Medicaid enrollees covered</td></tr>
<tr><td>Jan 5, 2026</td><td>Wegovy pill launches at $149 for the starting dose (<a href="https://www.cnn.com/2026/01/05/health/wegovy-pill-weight-loss" target="_blank" rel="noopener">CNN</a>)</td><td>New low-cost entry point</td></tr>
<tr><td>Feb 5, 2026</td><td>TrumpRx.gov launches (<a href="https://www.cnbc.com/2026/02/05/trump-rx-white-house-launches-direct-to-consumer-drug-site.html" target="_blank" rel="noopener">CNBC</a>)</td><td>One place to find manufacturer cash prices</td></tr>
<tr><td>Feb 23, 2026</td><td>Lilly prices the Zepbound KwikPen the same as vials (<a href="https://investor.lilly.com/news-releases/news-release-details/zepbound-tirzepatide-most-prescribed-weight-management" target="_blank" rel="noopener">Lilly</a>)</td><td>Pen convenience without a pen premium</td></tr>
<tr><td>Feb 24, 2026</td><td>Novo announces Wegovy list price cut to $675, effective Jan 1, 2027 (<a href="https://www.prnewswire.com/news-releases/novo-nordisk-announces-significant-reduction-in-us-list-price-for-wegovy-ozempic-and-rybelsus-semaglutide-medicines-building-on-continued-efforts-to-expand-access-302695705.html" target="_blank" rel="noopener">Novo</a>)</td><td>May lower deductible-phase costs for insured patients in 2027</td></tr>
<tr><td>Mar 19, 2026</td><td>FDA approves Wegovy HD 7.2 mg (<a href="https://www.prnewswire.com/news-releases/fda-approves-novo-nordisks-new-wegovy-hd-injection-delivering-the-highest-weight-loss-to-date-for-a-wegovy-injection-adding-to-its-already-expansive-clinical-profile-302718982.html" target="_blank" rel="noopener">Novo</a>)</td><td>New $399 self-pay option</td></tr>
<tr><td>Apr 1, 2026</td><td>FDA approves Foundayo (<a href="https://investor.lilly.com/news-releases/news-release-details/fda-approves-lillys-foundayotm-orforglipron-only-glp-1-pill" target="_blank" rel="noopener">Lilly</a>)</td><td>Second GLP-1 pill, starting at $149</td></tr>
<tr><td>Apr 21, 2026</td><td>CMS extends the Medicare Bridge through 2027 and delays BALANCE Part D (<a href="https://www.aha.org/news/headline/2026-04-22-cms-delays-part-d-portion-balance-model-expansion-glp-1-access" target="_blank" rel="noopener">AHA</a>)</td><td>More time at $50 for Medicare enrollees</td></tr>
<tr><td>Jul 1, 2026</td><td>Medicare GLP-1 Bridge starts (<a href="https://www.cms.gov/medicare/coverage/prescription-drug-coverage/medicare-glp-1-bridge" target="_blank" rel="noopener">CMS</a>)</td><td>$50 a month for eligible beneficiaries</td></tr>
<tr><td>Jan 1, 2027</td><td>Wegovy list price cut and $274 Medicare negotiated price take effect</td><td>Changes insurer and Medicare math, not cash prices</td></tr>
</tbody>
</table>
<h3>Competition from pills pushed prices down further</h3>
<p>The two new pills gave both companies a reason to compete on entry price. The <a href="https://www.cnn.com/2026/01/05/health/wegovy-pill-weight-loss" target="_blank" rel="noopener">Wegovy pill launched on January 5, 2026</a> at $149 a month for the 1.5 mg starting dose, and Lilly priced <a href="https://www.lilly.com/lillydirect/foundayo" target="_blank" rel="noopener">Foundayo</a> starting at $149 as well. Self-pay sales now matter a great deal to the manufacturers: <a href="https://www.medicaldaily.com/wegovy-self-pay-half-business-novo-nordisk-cash-price-478977" target="_blank" rel="noopener">Medical Daily reported</a> that self-pay channels make up about half of Wegovy's US business and about 90% of Wegovy pill demand.</p>`,
  },
  {
    heading: "What is the list price of Wegovy, Zepbound and other GLP-1s?",
    body: `<p>As of 2026, the list price of Wegovy is about $1,349 per 28-day supply and the list price of Zepbound is about $1,060-$1,090 a month. Novo Nordisk will cut the list price of Wegovy, Ozempic and Rybelsus to $675 a month on January 1, 2027.</p>
<p>The <a href="https://www.healthsystemtracker.org/brief/how-trumprx-brand-name-drug-prices-compare-to-other-countries/" target="_blank" rel="noopener">Peterson-KFF Health System Tracker</a> puts Wegovy's 2026 list price (its wholesale acquisition cost) at about $1,349, and NovoCare lists both the pen and the pill at $1,349.02 per package. Zepbound's list price is reported slightly differently by different sources: TrumpRx shows an "original" price of $1,087, <a href="https://www.ajmc.com/view/trumprx-launch-brings-savings-and-uncertainty" target="_blank" rel="noopener">AJMC cited $1,086</a>, and other sources say $1,059.87, so "about $1,060-$1,090" is the honest range.</p>
<h3>List prices now and in 2027</h3>
<table>
<thead><tr><th>Drug</th><th>List price per month (2026)</th><th>List price from Jan 1, 2027</th><th>Source</th></tr></thead>
<tbody>
<tr><td>Wegovy pen (2.4 mg and lower doses)</td><td>About $1,349</td><td>$675 (about 50% lower)</td><td><a href="https://www.prnewswire.com/news-releases/novo-nordisk-announces-significant-reduction-in-us-list-price-for-wegovy-ozempic-and-rybelsus-semaglutide-medicines-building-on-continued-efforts-to-expand-access-302695705.html" target="_blank" rel="noopener">Novo Nordisk</a></td></tr>
<tr><td>Wegovy pill (including 25 mg)</td><td>About $1,349</td><td>$675</td><td><a href="https://www.prnewswire.com/news-releases/novo-nordisk-announces-significant-reduction-in-us-list-price-for-wegovy-ozempic-and-rybelsus-semaglutide-medicines-building-on-continued-efforts-to-expand-access-302695705.html" target="_blank" rel="noopener">Novo Nordisk</a></td></tr>
<tr><td>Ozempic</td><td>About $1,000 (White House description before the Nov 2025 deal)</td><td>$675 (about 35% lower)</td><td><a href="https://www.ajmc.com/view/trump-announces-deals-with-eli-lilly-novo-nordisk-for-lower-weight-loss-drug-prices" target="_blank" rel="noopener">AJMC</a>, <a href="https://www.nbcnews.com/health/health-news/novo-nordisk-halve-us-list-price-wegovy-2027-rcna260413" target="_blank" rel="noopener">NBC News</a></td></tr>
<tr><td>Zepbound</td><td>About $1,060-$1,090</td><td>No announced change</td><td><a href="https://www.ajmc.com/view/trumprx-launch-brings-savings-and-uncertainty" target="_blank" rel="noopener">AJMC</a></td></tr>
</tbody>
</table>
<h3>What list price actually means</h3>
<p>List price is the manufacturer's starting price before rebates and discounts. Hardly anyone pays it in full, but it still matters in two ways:</p>
<ul>
<li><strong>Deductibles and coinsurance.</strong> If your plan covers a GLP-1 and you have not met your deductible, or you pay a percentage of the drug's cost, your share is often based on a price close to list. A lower list price can shrink that bill.</li>
<li><strong>Insurer and employer decisions.</strong> Plans weigh list prices (minus confidential rebates) when deciding whether to cover weight-loss drugs at all.</li>
</ul>
<p>Novo said the 2027 list price cut applies to all doses of Wegovy injection 2.4 mg and the 25 mg tablets, Ozempic and Rybelsus, and that it <strong>does not change</strong> its direct-to-patient self-pay prices, according to <a href="https://www.prnewswire.com/news-releases/novo-nordisk-announces-significant-reduction-in-us-list-price-for-wegovy-ozempic-and-rybelsus-semaglutide-medicines-building-on-continued-efforts-to-expand-access-302695705.html" target="_blank" rel="noopener">Novo Nordisk's February 24, 2026 announcement</a>. If you pay cash, the January 2027 cut does not lower what you pay. If you have insurance, ask your plan how it will apply.</p>
<h3>How US prices compare with other countries</h3>
<p>US prices have long been far higher than abroad. A 2023 Peterson-KFF analysis found Ozempic's US list price was $936 a month, compared with about $93 in the UK and $169 in Japan, as <a href="https://www.cnbc.com/2023/08/17/weight-loss-drugs-cost-more-in-us-kff-says.html" target="_blank" rel="noopener">CNBC reported</a>. Even after the 2026 cuts, a <a href="https://www.healthsystemtracker.org/brief/how-trumprx-brand-name-drug-prices-compare-to-other-countries/" target="_blank" rel="noopener">Peterson-KFF comparison using prices as of August 25, 2026</a> found the $349 TrumpRx cash price for the Ozempic pen was the highest among 11 peer countries, where the next-highest price was $190. The $449 Zepbound KwikPen maintenance price was also the highest (the next was $423). Only Germany charged more for the Wegovy pen, at $427 versus $349.</p>`,
  },
  {
    heading: "How much does Wegovy cost without insurance in 2026?",
    body: `<p>Without insurance, the Wegovy pen costs $349 a month at every dose from 0.25 mg to 2.4 mg through NovoCare and TrumpRx as of October 2026, and new self-pay patients can get their first two fills of the 0.25 mg and 0.5 mg doses for $199 each through December 31, 2026. Wegovy HD (7.2 mg) costs $399 a month.</p>
<p>Those prices come from the <a href="https://www.novocare.com/content/dam/novonordisk/novocare/redesign/pdf/Wegovy_Price_Guide.pdf" target="_blank" rel="noopener">NovoCare Wegovy price guide</a> and the <a href="https://www.novocare.com/patient/medicines/wegovy/savings-offer.html" target="_blank" rel="noopener">NovoCare savings offer page</a>. Novo Nordisk first cut its standard self-pay price from $499 to $349 and launched the $199 introductory price on November 17, 2025, according to <a href="https://www.prnewswire.com/news-releases/novo-nordisk-launches-introductory-self-pay-offer-for-wegovy-and-ozempic-for-199-per-month-302617100.html" target="_blank" rel="noopener">Novo Nordisk</a>. That original announcement said the intro offer would end March 31, 2026. NovoCare later extended it through December 31, 2026.</p>
<h3>Wegovy self-pay price by dose</h3>
<table>
<thead><tr><th>Wegovy dose</th><th>Self-pay price per month (as of October 2026)</th><th>Notes</th></tr></thead>
<tbody>
<tr><td>0.25 mg (pen)</td><td>$199 intro, then $349</td><td>Intro price for new self-pay patients, first two monthly fills of 0.25 mg and 0.5 mg, through Dec 31, 2026</td></tr>
<tr><td>0.5 mg (pen)</td><td>$199 intro, then $349</td><td>Same intro offer as above</td></tr>
<tr><td>Higher doses up to 2.4 mg (pen)</td><td>$349</td><td>Flat price regardless of dose</td></tr>
<tr><td>Wegovy HD 7.2 mg (injection)</td><td>$399</td><td>NovoCare says insurance coverage is not available for 7.2 mg</td></tr>
</tbody>
</table>
<p>Sources: <a href="https://www.novocare.com/content/dam/novonordisk/novocare/redesign/pdf/Wegovy_Price_Guide.pdf" target="_blank" rel="noopener">NovoCare price guide</a>; <a href="https://www.novocare.com/patient/medicines/wegovy/check-coverage.html" target="_blank" rel="noopener">NovoCare coverage page</a>.</p>
<h3>Why the flat price matters</h3>
<p>A flat $349 price across doses is good news if you need a higher dose. With many drugs, you pay more as the dose rises. With the Wegovy pen, the 2.4 mg maintenance dose costs the same as the starting dose once the intro period ends. If you start in late 2026 and use both $199 intro fills, your first two months cost $398 total, and each month after that costs $349 at today's prices. Our guide to <a href="/articles/glp1-true-cost-month-1-vs-year-one">GLP-1 costs in month 1 vs year one</a> shows how those numbers add up.</p>
<h3>What about Wegovy HD?</h3>
<p>The FDA approved Wegovy HD (semaglutide 7.2 mg) on March 19, 2026, for adults who have tolerated 2.4 mg for at least four weeks and need more weight loss, according to <a href="https://www.prnewswire.com/news-releases/fda-approves-novo-nordisks-new-wegovy-hd-injection-delivering-the-highest-weight-loss-to-date-for-a-wegovy-injection-adding-to-its-already-expansive-clinical-profile-302718982.html" target="_blank" rel="noopener">Novo Nordisk</a>. In the STEP UP trial it produced 20.7% mean weight loss. At $399 a month self-pay, it costs $50 more than the standard pen, and the <a href="https://www.novocare.com/patient/medicines/wegovy/check-coverage.html" target="_blank" rel="noopener">NovoCare coverage page</a> says insurance coverage is not available for the 7.2 mg injection. Whether the higher dose is right for you is a question for your clinician.</p>
<h3>Where to buy Wegovy at the self-pay price</h3>
<p>Novo's self-pay pricing is available through NovoCare Pharmacy, retail and telehealth partners, and a digital savings card that Novo says is accepted at more than 70,000 US pharmacies, according to <a href="https://www.prnewswire.com/news-releases/novo-nordisk-launches-introductory-self-pay-offer-for-wegovy-and-ozempic-for-199-per-month-302617100.html" target="_blank" rel="noopener">Novo Nordisk</a>. TrumpRx lists the same prices and points you to these channels rather than selling the drug itself. You need a valid prescription in every case. If you would like help finding a prescriber, our <a href="/find-your-match">provider match tool</a> can point you to telehealth options.</p>`,
  },
  {
    heading: "How much does the Wegovy pill cost?",
    body: `<p>The Wegovy pill costs $149 a month for the 1.5 mg starting dose, $199 for the 4 mg dose, and $299 for the 9 mg and 25 mg doses when you pay cash, as of October 2026. With insurance that covers it, Novo Nordisk says the pill can cost as little as $25 a month.</p>
<p>The FDA approved the Wegovy pill (oral semaglutide) on December 22, 2025, as the first oral GLP-1 approved for weight loss, according to <a href="https://www.prnewswire.com/news-releases/fda-approves-novo-nordisks-wegovy-pill-the-first-and-only-oral-glp-1-for-weight-loss-in-adults-302648344.html" target="_blank" rel="noopener">Novo Nordisk</a> and <a href="https://www.cnn.com/2025/12/22/health/wegovy-pill-glp1-weight-loss-drugs" target="_blank" rel="noopener">CNN</a>. It launched in the US on January 5, 2026, sold through NovoCare Pharmacy, retail pharmacies such as CVS and Costco, and telehealth services such as GoodRx, ro and LifeMD, as <a href="https://www.cnn.com/2026/01/05/health/wegovy-pill-weight-loss" target="_blank" rel="noopener">CNN reported</a>.</p>
<h3>Wegovy pill self-pay price by dose</h3>
<table>
<thead><tr><th>Wegovy pill dose</th><th>Self-pay price per month (as of October 2026)</th><th>Price history</th></tr></thead>
<tbody>
<tr><td>1.5 mg (starting dose)</td><td>$149</td><td>Unchanged since the January 2026 launch</td></tr>
<tr><td>4 mg</td><td>$199</td><td>Was $149 through April 15, 2026</td></tr>
<tr><td>9 mg</td><td>$299</td><td>Unchanged since launch</td></tr>
<tr><td>25 mg (highest dose)</td><td>$299</td><td>Unchanged since launch</td></tr>
</tbody>
</table>
<p>Sources: <a href="https://www.cnn.com/2026/01/06/health/wegovy-pill-weight-loss-explained" target="_blank" rel="noopener">CNN</a>; <a href="https://investors.goodrx.com/news-releases/news-release-details/goodrx-now-offers-novo-nordisks-cash-price-launch-wegovyr-pill/" target="_blank" rel="noopener">GoodRx</a>; <a href="https://www.novocare.com/content/dam/novonordisk/novocare/redesign/pdf/Wegovy_Price_Guide.pdf" target="_blank" rel="noopener">NovoCare price guide</a>.</p>
<h3>Is the pill cheaper than the pen?</h3>
<p>At the top dose, yes. The 25 mg Wegovy pill costs $299 a month self-pay, while the Wegovy pen costs $349 at every dose, based on the <a href="https://www.novocare.com/content/dam/novonordisk/novocare/redesign/pdf/Wegovy_Price_Guide.pdf" target="_blank" rel="noopener">NovoCare price guide</a>. That is a $50 monthly difference, or $600 over a year at maintenance. At the start, the comparison depends on timing: the pen's $199 intro price for the first two fills runs through December 31, 2026, while the pill's 1.5 mg starting dose is $149.</p>
<p>Price is not the only difference. In the OASIS 4 trial, the 25 mg Wegovy pill produced 13.6% average weight loss at 64 weeks versus 2.2% on placebo, according to <a href="https://www.prnewswire.com/news-releases/fda-approves-novo-nordisks-wegovy-pill-the-first-and-only-oral-glp-1-for-weight-loss-in-adults-302648344.html" target="_blank" rel="noopener">Novo Nordisk's approval announcement</a>. In the STEP 1 trial, the 2.4 mg Wegovy injection produced 14.9% mean weight loss at 68 weeks, per the <a href="https://www.nejm.org/doi/full/10.1056/NEJMoa2032183" target="_blank" rel="noopener">New England Journal of Medicine</a>. These are different trials, so the comparison is approximate. Your clinician can help you weigh the daily pill routine against a weekly shot.</p>
<h3>Self-pay is how most people buy the pill</h3>
<p>Cash buyers drive this product. <a href="https://www.medicaldaily.com/wegovy-self-pay-half-business-novo-nordisk-cash-price-478977" target="_blank" rel="noopener">Medical Daily reported</a> that self-pay channels account for about 90% of Wegovy pill demand. With insurance that covers it, the pill can cost as little as $25 a month according to Novo's website, as <a href="https://www.fiercepharma.com/pharma/novos-wegovy-pill-makes-us-debut-starter-dose-launching-149-month-cash-paying-patients" target="_blank" rel="noopener">Fierce Pharma reported</a>. The pill is also covered by the Medicare GLP-1 Bridge at $50 a month for people who qualify (see the Medicare sections below).</p>
<p>Comparing the two GLP-1 pills? Our breakdown of <a href="/articles/foundayo-vs-wegovy-pill">Foundayo vs the Wegovy pill</a> covers dosing, food rules and cost side by side.</p>`,
  },
  {
    heading: "How much does Zepbound cost without insurance in 2026?",
    body: `<p>Without insurance, Zepbound costs $299 a month for 2.5 mg, $399 for 5 mg and $449 for 7.5 mg through 15 mg through LillyDirect as of October 2026, whether you choose the single-dose vial or the multi-dose KwikPen. The $449 price for higher doses applies only if you refill within 45 days of your last delivery.</p>
<p>Lilly set those prices on December 1, 2025, cutting Zepbound vials from $349-$499 a month, as <a href="https://www.cnbc.com/2025/12/01/eli-lilly-prices-zepbound-weight-loss-drug-vials.html" target="_blank" rel="noopener">CNBC reported</a>. The FDA approved the multi-dose Zepbound KwikPen in late January 2026, per <a href="https://www.fiercepharma.com/marketing/lilly-adds-multidose-zepbound-pens-self-pay-menu-after-fda-nod" target="_blank" rel="noopener">Fierce Pharma</a>, and on February 23, 2026 Lilly said all Zepbound doses are available as the KwikPen or the vial at the same self-pay price, starting at $299 a month, according to <a href="https://investor.lilly.com/news-releases/news-release-details/zepbound-tirzepatide-most-prescribed-weight-management" target="_blank" rel="noopener">Lilly</a>.</p>
<h3>Zepbound self-pay price by dose</h3>
<table>
<thead><tr><th>Zepbound dose</th><th>Vial (per month)</th><th>KwikPen (per month)</th><th>Condition</th></tr></thead>
<tbody>
<tr><td>2.5 mg</td><td>$299</td><td>$299</td><td>None</td></tr>
<tr><td>5 mg</td><td>$399</td><td>$399</td><td>None</td></tr>
<tr><td>7.5 mg</td><td>$449</td><td>$449</td><td>Refill within 45 days of last delivery</td></tr>
<tr><td>10 mg</td><td>$449</td><td>$449</td><td>Refill within 45 days of last delivery</td></tr>
<tr><td>12.5 mg</td><td>$449</td><td>$449</td><td>Refill within 45 days of last delivery</td></tr>
<tr><td>15 mg</td><td>$449</td><td>$449</td><td>Refill within 45 days of last delivery</td></tr>
</tbody>
</table>
<p>Sources, prices as of October 2026: <a href="https://www.lilly.com/lillydirect/zepbound" target="_blank" rel="noopener">LillyDirect</a>; <a href="https://www.walgreens.com/topic/virtual-healthcare/weight-loss/zepbound.jsp" target="_blank" rel="noopener">Walgreens</a>, which says Lilly offers the KwikPen at these prices to eligible self-pay patients through December 31, 2026.</p>
<h3>The 45-day refill rule</h3>
<p>The single most important detail on Zepbound pricing is the refill window. <a href="https://www.lilly.com/lillydirect/zepbound" target="_blank" rel="noopener">Lilly's LillyDirect page</a> lists the $449 price for 7.5 mg to 15 mg only when you refill within 45 days of your last delivery. If you refill late, the price is higher. Reported late-refill prices vary from source to source, so check LillyDirect for the current figure before you let a refill slip. A few practical habits help:</p>
<ul>
<li>Set a calendar reminder about a week before day 45.</li>
<li>Plan around travel, so a trip does not push your next order outside the window.</li>
<li>If you pause treatment on purpose, ask LillyDirect what you will pay when you restart.</li>
</ul>
<h3>Who can use the Zepbound self-pay price</h3>
<p>Lilly's self-pay program requires that you are 18 or older, live in the US or Puerto Rico, and have a valid prescription for an FDA-approved use. It covers the KwikPen and vials, not the single-dose autoinjector pen, and it cannot be billed to insurance, according to <a href="https://www.lilly.com/lillydirect/zepbound" target="_blank" rel="noopener">LillyDirect</a> and <a href="https://prescriberpoint.com/therapies/zepbound-487cd7e/financial-assistance/lilly-direct-zepbound" target="_blank" rel="noopener">PrescriberPoint</a>. Lilly's KwikPen self-pay pricing was also reportedly extended to retail pharmacies such as Costco, Walmart, CVS and Walgreens through a self-pay savings card starting in March 2026, per <a href="https://www.noom.com/blog/weight-management/zepbound-cost-without-insurance/" target="_blank" rel="noopener">Noom</a> and the <a href="https://www.walgreens.com/topic/virtual-healthcare/weight-loss/zepbound.jsp" target="_blank" rel="noopener">Walgreens Zepbound page</a>.</p>
<h3>Is Zepbound worth the extra cost?</h3>
<p>At $449 for maintenance doses, Zepbound costs $100 a month more than the Wegovy pen. In the SURMOUNT-1 trial, tirzepatide 15 mg produced 20.9% mean weight loss at 72 weeks, according to the <a href="https://www.nejm.org/doi/full/10.1056/NEJMoa2206038" target="_blank" rel="noopener">New England Journal of Medicine</a>, compared with 14.9% for semaglutide 2.4 mg in STEP 1, a separate trial. For a dose-by-dose look at where to buy, see our guide to <a href="/articles/zepbound-price-online">Zepbound prices online</a>.</p>`,
  },
  {
    heading: "How much does Foundayo cost?",
    body: `<p>Foundayo (orforglipron), Eli Lilly's once-daily GLP-1 pill, costs $149 to $349 a month self-pay through LillyDirect and TrumpRx as of October 2026, depending on dose and refill timing. Through December 31, 2026, Lilly has temporarily cut the 2.5 mg dose to $149 and the 5.5 mg dose to $199.</p>
<p>The FDA approved Foundayo for weight loss on April 1, 2026. Unlike the Wegovy pill, it can be taken any time of day without food or water restrictions, according to <a href="https://investor.lilly.com/news-releases/news-release-details/fda-approves-lillys-foundayotm-orforglipron-only-glp-1-pill" target="_blank" rel="noopener">Lilly's approval announcement</a>. Lilly began taking prescriptions through LillyDirect on approval day and started shipping on April 6, 2026, followed by retail pharmacy and telehealth availability.</p>
<h3>Foundayo self-pay price by dose</h3>
<table>
<thead><tr><th>Foundayo dose</th><th>Regular self-pay price</th><th>Temporary price through Dec 31, 2026</th></tr></thead>
<tbody>
<tr><td>0.8 mg (starting dose)</td><td>$149</td><td>$149</td></tr>
<tr><td>2.5 mg</td><td>$199</td><td>$149</td></tr>
<tr><td>5.5 mg</td><td>$299</td><td>$199</td></tr>
<tr><td>9 mg</td><td>$299</td><td>$299</td></tr>
<tr><td>14.5 mg</td><td>$299 if refilled within 45 days, otherwise $349</td><td>Same</td></tr>
<tr><td>17.2 mg (highest dose)</td><td>$299 if refilled within 45 days, otherwise $349</td><td>Same</td></tr>
</tbody>
</table>
<p>Sources, prices as of October 2026: <a href="https://www.lilly.com/lillydirect/foundayo" target="_blank" rel="noopener">LillyDirect</a>; <a href="https://trumprx.gov/p/foundayo" target="_blank" rel="noopener">TrumpRx</a>; <a href="https://foundayo.lilly.com/hcp/savings-coverage" target="_blank" rel="noopener">Lilly Foundayo savings and coverage page</a>; <a href="https://www.goodrx.com/conditions/weight-loss/orforglipron-danuglipron-new-weight-loss-drug" target="_blank" rel="noopener">GoodRx</a>.</p>
<h3>What the temporary prices mean for you</h3>
<p>If you start Foundayo before the end of 2026, your first three dose levels can each cost $149-$199 a month, based on the <a href="https://foundayo.lilly.com/hcp/savings-coverage" target="_blank" rel="noopener">temporary prices Lilly lists through December 31, 2026</a>. After that date, Lilly may return to the regular schedule, extend the cuts or change prices again, so do not count on the lower prices lasting into 2027. At maintenance, Foundayo's regular price of $299 a month matches the 9 mg and 25 mg Wegovy pill and sits $50 below the Wegovy pen.</p>
<p>The same 45-day refill window that applies to higher Zepbound doses applies to the two highest Foundayo doses. Refill 14.5 mg or 17.2 mg late and the price rises from $299 to $349, according to <a href="https://www.lilly.com/lillydirect/foundayo" target="_blank" rel="noopener">LillyDirect</a>.</p>
<h3>Foundayo with insurance or Medicare</h3>
<ul>
<li><strong>Commercial insurance:</strong> commercially insured patients whose plan covers Foundayo may pay as little as $25 a month with the Foundayo savings card, per <a href="https://investor.lilly.com/news-releases/news-release-details/fda-approves-lillys-foundayotm-orforglipron-only-glp-1-pill" target="_blank" rel="noopener">Lilly</a>. Terms can change, so check before each fill.</li>
<li><strong>Formulary access:</strong> CVS Caremark removed its new-to-market block on Foundayo effective June 1, 2026, according to <a href="https://www.managedhealthcareexecutive.com/view/cvs-caremark-to-put-zepbound-back-on-formulary-and-add-foundayo" target="_blank" rel="noopener">Managed Healthcare Executive</a>. Employer plans can still customize their coverage.</li>
<li><strong>Medicare:</strong> Foundayo is one of the drugs covered by the Medicare GLP-1 Bridge at $50 a month for people who qualify, according to <a href="https://www.aarp.org/medicare/glp1-weight-loss-copay-program/" target="_blank" rel="noopener">AARP</a>.</li>
</ul>
<h3>How well does Foundayo work for the price?</h3>
<p>In the ATTAIN-1 trial, people on the highest Foundayo dose lost an average of about 27 pounds, or about 11%-12% of body weight, according to <a href="https://www.barchart.com/story/news/1093875/fda-approves-lilly-s-foundayo-orforglipron-the-only-glp-1-pill-for-weight-loss-that-can-be-taken-any-time-of-day-without-food-or-water-restrictions" target="_blank" rel="noopener">Lilly's approval release</a>. No head-to-head trial has compared Foundayo with the Wegovy pill, so any comparison across trials is approximate, as <a href="https://remyresearch.com/research/orforglipron-vs-wegovy-pill" target="_blank" rel="noopener">Remy Research notes</a>. If you value flexible timing over the last few percentage points of weight loss, Foundayo's lack of food rules may be worth more to you than a small price difference.</p>`,
  },
  {
    heading: "What is TrumpRx, and is it cheaper than buying direct?",
    body: `<p>TrumpRx.gov is a federal website, launched February 5, 2026, that sends cash-paying patients with a valid prescription to drugmakers' own direct-to-consumer programs, such as LillyDirect and NovoCare, or gives them a coupon to use at a pharmacy. For GLP-1s, TrumpRx is not cheaper than buying direct: its prices match the manufacturers' self-pay prices as of October 2026.</p>
<p>The White House launched TrumpRx after missing a planned January launch, according to <a href="https://www.cnbc.com/2026/02/05/trump-rx-white-house-launches-direct-to-consumer-drug-site.html" target="_blank" rel="noopener">CNBC</a> and the <a href="https://www.whitehouse.gov/fact-sheets/2026/02/fact-sheet-president-donald-j-trump-launches-trumprx-gov-to-bring-lower-drug-prices-to-american-patients/" target="_blank" rel="noopener">White House fact sheet</a>. Some outlets dated the launch February 6. At launch, the site listed about 40-43 brand-name drugs from five manufacturers, per <a href="https://www.ajmc.com/view/trumprx-launch-brings-savings-and-uncertainty" target="_blank" rel="noopener">AJMC</a>, and it added generic medicines in May 2026, according to the <a href="https://www.whitehouse.gov/fact-sheets/2026/05/fact-sheet-president-donald-j-trump-announces-expansion-of-trumprx-gov-to-bring-americans-transparency-and-choice-on-everyday-medicines/" target="_blank" rel="noopener">White House</a>.</p>
<h3>What TrumpRx does and does not do</h3>
<table>
<thead><tr><th>TrumpRx does</th><th>TrumpRx does not</th></tr></thead>
<tbody>
<tr><td>Show manufacturer cash prices in one place</td><td>Sell or ship drugs itself</td></tr>
<tr><td>Route you to LillyDirect, NovoCare and other manufacturer programs</td><td>Bill your insurance</td></tr>
<tr><td>Provide pharmacy coupons for some drugs</td><td>Write prescriptions (you still need one from a licensed clinician)</td></tr>
<tr><td>List both brand-name and, since May 2026, generic drugs</td><td>Offer GLP-1 prices below the manufacturers' own self-pay prices</td></tr>
</tbody>
</table>
<p>Sources: <a href="https://www.cnbc.com/2026/02/05/trump-rx-white-house-launches-direct-to-consumer-drug-site.html" target="_blank" rel="noopener">CNBC</a>; <a href="https://www.congress.gov/crs-product/IF13281" target="_blank" rel="noopener">Congressional Research Service</a>; <a href="https://therxindex.com/trumprx-zepbound/" target="_blank" rel="noopener">The Rx Index</a>.</p>
<h3>TrumpRx vs buying direct: GLP-1 prices compared</h3>
<table>
<thead><tr><th>Drug</th><th>TrumpRx price (as of October 2026)</th><th>Direct from manufacturer</th></tr></thead>
<tbody>
<tr><td>Wegovy pen</td><td>$199 intro, then $349</td><td>Same on NovoCare</td></tr>
<tr><td>Wegovy pill</td><td>$149-$299 by dose</td><td>Same on NovoCare</td></tr>
<tr><td>Zepbound vial or KwikPen</td><td>$299-$449 by dose</td><td>Same on LillyDirect</td></tr>
<tr><td>Foundayo</td><td>$149-$349 by dose and refill timing</td><td>Same on LillyDirect</td></tr>
</tbody>
</table>
<p>Sources: <a href="https://therxindex.com/trumprx-zepbound/" target="_blank" rel="noopener">The Rx Index</a>; <a href="https://trumprx.gov/p/foundayo" target="_blank" rel="noopener">TrumpRx Foundayo page</a>; <a href="https://www.novocare.com/content/dam/novonordisk/novocare/redesign/pdf/Wegovy_Price_Guide.pdf" target="_blank" rel="noopener">NovoCare price guide</a>; <a href="https://www.lilly.com/lillydirect/zepbound" target="_blank" rel="noopener">LillyDirect</a>.</p>
<h3>Who TrumpRx helps most</h3>
<p>TrumpRx is most useful as a starting point if you are uninsured or your plan does not cover weight-loss drugs, because it lets you see the cash prices without visiting each manufacturer's site. If you have insurance, the math is less clear. <a href="https://www.cnbc.com/2026/02/05/trump-rx-white-house-launches-direct-to-consumer-drug-site.html" target="_blank" rel="noopener">CNBC noted at launch</a> that it was unclear whether insured patients would save money through TrumpRx. Cash purchases generally do not count toward your insurance deductible, though you should check your own plan's rules.</p>
<p>The White House said in October 2026 that patients had saved more than $700 million through TrumpRx since launch, according to a <a href="https://whitehouse.gov/fact-sheets/2026/10/fact-sheet-president-donald-j-trump-and-first-lady-melania-trump-advance-womens-health-to-improve-outcomes-in-all-phases-of-life" target="_blank" rel="noopener">White House fact sheet</a>. That is the administration's own figure and has not been independently verified.</p>
<h3>How to use TrumpRx for a GLP-1</h3>
<ol>
<li>Get a valid prescription from a licensed clinician, in person or through telehealth.</li>
<li>Look up your drug and dose on TrumpRx.gov and note the listed cash price.</li>
<li>Follow the link to the manufacturer program (LillyDirect or NovoCare) or download the pharmacy coupon if one is offered.</li>
<li>Check refill-timing rules and any introductory price end dates before you order.</li>
<li>Save your receipts. If your drug is prescribed for a diagnosed condition, you may be able to use HSA or FSA funds, which the second half of this guide explains.</li>
</ol>`,
  },
  {
    heading: "Does Medicare cover GLP-1s for weight loss in 2026?",
    body: `<p>Yes, for the first time: from July 1, 2026 through December 31, 2027, the Medicare GLP-1 Bridge lets eligible Medicare beneficiaries get Wegovy, the Zepbound KwikPen or Foundayo for weight loss for a $50 copay per monthly supply. Outside the Bridge, Medicare Part D still generally excludes drugs used only for weight loss.</p>
<p>The exclusion comes from the Part D law itself, which is why weight-loss coverage needed a special demonstration program, as <a href="https://www.medicare.gov/coverage/weight-loss-drugs" target="_blank" rel="noopener">Medicare.gov</a> and <a href="https://www.kff.org/medicare/what-to-know-about-the-balance-model-for-glp-1s-in-medicare-and-medicaid/" target="_blank" rel="noopener">KFF</a> explain. The Bridge began on July 1, 2026, according to <a href="https://www.cms.gov/medicare/coverage/prescription-drug-coverage/medicare-glp-1-bridge" target="_blank" rel="noopener">CMS</a> and <a href="https://www.cnbc.com/2026/06/30/medicare-obesity-drug-glp-1-coverage-starting-july-1.html" target="_blank" rel="noopener">CNBC</a>. It was originally set to end in December 2026, but CMS extended it through December 2027 in an April 21, 2026 memo, according to <a href="https://www.aha.org/news/headline/2026-04-22-cms-delays-part-d-portion-balance-model-expansion-glp-1-access" target="_blank" rel="noopener">AHA News</a> and <a href="https://www.kff.org/quick-insights/cms-extends-medicares-short-term-bridge-program-for-glp-1-obesity-drug-coverage/" target="_blank" rel="noopener">KFF</a>.</p>
<h3>Medicare GLP-1 Bridge at a glance</h3>
<table>
<thead><tr><th>Feature</th><th>Details (as of October 2026)</th></tr></thead>
<tbody>
<tr><td>Dates</td><td>July 1, 2026 through December 31, 2027</td></tr>
<tr><td>Your cost</td><td>$50 for a one-month supply (28 or 30 days, depending on the drug)</td></tr>
<tr><td>What Medicare pays the manufacturer</td><td>$245 net per monthly supply</td></tr>
<tr><td>Who runs claims and prior authorization</td><td>A single CMS central processor, not your Part D plan</td></tr>
<tr><td>Who is eligible</td><td>Part D or Medicare Advantage drug plan enrollees who meet BMI and clinical criteria</td></tr>
</tbody>
</table>
<p>Sources: <a href="https://www.npr.org/2026/05/06/nx-s1-5812662/medicare-bridge-glp1-drugs-copay" target="_blank" rel="noopener">NPR</a>; <a href="https://www.cms.gov/files/document/medicare-glp-1-bridge-expectations-faqs.pdf" target="_blank" rel="noopener">CMS Bridge FAQ</a>; <a href="https://www.ncoa.org/article/expanding-access-to-weight-loss-medications-the-medicare-glp-1-bridge-program/" target="_blank" rel="noopener">NCOA</a>.</p>
<h3>Which drugs the Bridge covers</h3>
<table>
<thead><tr><th>Drug</th><th>Covered by the Bridge?</th></tr></thead>
<tbody>
<tr><td>Wegovy pen, all doses</td><td>Yes</td></tr>
<tr><td>Wegovy pill, all doses</td><td>Yes</td></tr>
<tr><td>Zepbound KwikPen</td><td>Yes</td></tr>
<tr><td>Zepbound single-dose pens and vials</td><td>No</td></tr>
<tr><td>Foundayo</td><td>Yes</td></tr>
<tr><td>Ozempic and Mounjaro</td><td>No (still covered under regular Part D for type 2 diabetes)</td></tr>
</tbody>
</table>
<p>Sources: <a href="https://www.aarp.org/medicare/glp1-weight-loss-copay-program/" target="_blank" rel="noopener">AARP</a>; <a href="https://www.ncoa.org/article/expanding-access-to-weight-loss-medications-the-medicare-glp-1-bridge-program/" target="_blank" rel="noopener">NCOA</a>.</p>
<h3>How the Bridge is paid for</h3>
<p>Manufacturers supply Bridge drugs to Medicare at a net price of $245 per monthly supply, according to the <a href="https://www.cms.gov/files/document/medicare-glp-1-bridge-expectations-faqs.pdf" target="_blank" rel="noopener">CMS Bridge FAQ</a>. That price comes from the November 2025 deal with Lilly and Novo. Part D plans carry no financial risk for Bridge drugs and do not have to opt in. CMS uses one central processor for prior authorization, claims and pharmacy payment, which is why your prescriber sends paperwork there rather than to your plan.</p>
<p>At the time of the deal, about 10% of Medicare beneficiaries were expected to qualify, according to <a href="https://www.emarketer.com/content/glp-1-makers-slash-drug-prices-medicare-expansion-under-trump-pharma-deal" target="_blank" rel="noopener">eMarketer</a>. Compared with the $349 cash price of the Wegovy pen as of October 2026, a $50 copay saves an eligible beneficiary about $299 a month at current prices.</p>
<h3>Medicare coverage outside the Bridge</h3>
<p>Some GLP-1 uses were already covered by Part D before the Bridge. Wegovy is FDA-approved to reduce the risk of major cardiovascular events in adults with established cardiovascular disease and obesity or overweight, and Zepbound is approved for moderate-to-severe obstructive sleep apnea with obesity. Those indications can qualify for Part D coverage where weight loss alone does not, according to <a href="https://www.cms.gov/medicare/coverage/prescription-drug-coverage/medicare-glp-1-bridge/information-part-d-plans" target="_blank" rel="noopener">CMS</a> and <a href="https://www.aarp.org/medicare/does-medicare-cover-ozempic-weight-loss-drugs/" target="_blank" rel="noopener">AARP</a>. In those cases, your cost follows your regular Part D plan rules, not the $50 Bridge copay.</p>`,
  },
  {
    heading: "Who qualifies for the $50 Medicare GLP-1 Bridge?",
    body: `<p>You qualify for the $50 Medicare GLP-1 Bridge if you are enrolled in a standalone Part D plan or a Medicare Advantage plan with drug coverage, you meet one of three BMI-plus-condition tiers (starting at BMI 35 alone), and your prescriber gets prior authorization approved through CMS's central processor. People who already get a GLP-1 through Part D for another condition stay with their regular plan instead.</p>
<h3>Plan requirements</h3>
<p>To use the Bridge, you must be enrolled in a standalone Part D prescription drug plan (PDP) or a Medicare Advantage plan with drug coverage (MA-PD). PACE and private fee-for-service-only plans are excluded, according to <a href="https://www.sheppard.com/insights/blogs/medicares-50-per-month-glp1-bridge-what-you-need-to-know" target="_blank" rel="noopener">Sheppard Mullin</a> and <a href="https://www.ncoa.org/article/expanding-access-to-weight-loss-medications-the-medicare-glp-1-bridge-program/" target="_blank" rel="noopener">NCOA</a>. Your Part D plan does not need to opt in, because CMS runs the program centrally.</p>
<h3>Clinical eligibility: the three BMI tiers</h3>
<table>
<thead><tr><th>BMI</th><th>Also required</th></tr></thead>
<tbody>
<tr><td>35 or higher</td><td>Nothing else; BMI alone qualifies</td></tr>
<tr><td>30 or higher</td><td>At least one of: heart failure with preserved ejection fraction, uncontrolled hypertension, or chronic kidney disease stage 3a or higher</td></tr>
<tr><td>27 or higher</td><td>At least one of: prediabetes, a prior heart attack or stroke, or symptomatic peripheral artery disease</td></tr>
</tbody>
</table>
<p>Sources: <a href="https://www.ncoa.org/article/expanding-access-to-weight-loss-medications-the-medicare-glp-1-bridge-program/" target="_blank" rel="noopener">NCOA</a>; <a href="https://www.ajmc.com/view/medicare-glp-1-bridge-launches-but-who-actually-qualifies-" target="_blank" rel="noopener">AJMC</a>. Sources word the kidney disease criterion slightly differently, so confirm the exact language on <a href="https://www.cms.gov/medicare/coverage/prescription-drug-coverage/medicare-glp-1-bridge" target="_blank" rel="noopener">CMS's Bridge page</a>.</p>
<p>These tiers are stricter than the FDA label criteria many private insurers mirror, which generally start at BMI 30, or BMI 27 with at least one weight-related condition, as <a href="https://www.goodrx.com/conditions/weight-loss/orforglipron-danuglipron-new-weight-loss-drug" target="_blank" rel="noopener">GoodRx summarizes</a>. A Medicare enrollee with a BMI of 32 and no listed condition, for example, would not qualify for the Bridge. For a broader look at who can get these drugs, see our guide to <a href="/articles/who-qualifies-for-glp1-weight-loss">who qualifies for GLP-1 weight loss treatment</a>.</p>
<h3>Your BMI is judged from when you started</h3>
<p>Clinical criteria are judged as of when your GLP-1 therapy first started, including if you began before joining Part D or before July 1, 2026, according to <a href="https://www.ncoa.org/article/expanding-access-to-weight-loss-medications-the-medicare-glp-1-bridge-program/" target="_blank" rel="noopener">NCOA</a> and <a href="https://www.cnbc.com/2026/06/30/medicare-obesity-drug-glp-1-coverage-starting-july-1.html" target="_blank" rel="noopener">CNBC</a>. Prescribers must attest that you met the criteria at that time. This matters if you have already lost weight on a GLP-1 you paid for yourself: your current, lower BMI does not disqualify you as long as your starting BMI and conditions met a tier.</p>
<h3>Who gets routed to their regular Part D plan instead</h3>
<p>People who already get a GLP-1 covered by Part D for another FDA-approved use go through their regular plan, not the Bridge. Examples include type 2 diabetes, moderate-to-severe obstructive sleep apnea, MASH, or Wegovy for cardiovascular risk reduction in established heart disease, according to <a href="https://www.cms.gov/medicare/coverage/prescription-drug-coverage/medicare-glp-1-bridge/information-part-d-plans" target="_blank" rel="noopener">CMS</a> and <a href="https://www.npr.org/2026/05/06/nx-s1-5812662/medicare-bridge-glp1-drugs-copay" target="_blank" rel="noopener">NPR</a>. <a href="https://www.kff.org/medicare/nearly-four-million-medicare-beneficiaries-could-be-eligible-for-the-temporary-medicare-glp-1-bridge-program-covering-these-drugs-for-weight-loss/" target="_blank" rel="noopener">KFF notes</a> that eligibility also excludes Part D enrollees who already filled a GLP-1 prescription through their Part D plan in 2026.</p>
<h3>How many people qualify</h3>
<table>
<thead><tr><th>Group (KFF estimate, based on 2023 data)</th><th>Number of Medicare beneficiaries</th></tr></thead>
<tbody>
<tr><td>Met the BMI thresholds</td><td>More than 13 million</td></tr>
<tr><td>In Part D and met the clinical criteria</td><td>9.7 million</td></tr>
<tr><td>Met all Bridge eligibility criteria</td><td>3.8 million</td></tr>
</tbody>
</table>
<p>Source: <a href="https://www.kff.org/medicare/nearly-four-million-medicare-beneficiaries-could-be-eligible-for-the-temporary-medicare-glp-1-bridge-program-covering-these-drugs-for-weight-loss/" target="_blank" rel="noopener">KFF, June 29, 2026</a>. If you are unsure which group you fall into, bring your BMI history and diagnoses to your prescriber and ask them to check the criteria with you.</p>`,
  },
  {
    heading: "How do you get the $50 Medicare GLP-1 copay, step by step?",
    body: `<p>To get the $50 Medicare GLP-1 copay, confirm you have Part D or a Medicare Advantage drug plan, ask your prescriber to send a prescription and prior authorization request to the Medicare GLP-1 Bridge's central processor (not to your Part D plan), and then fill the approved prescription at a pharmacy for $50 per monthly supply.</p>
<h3>Step by step</h3>
<ol>
<li><strong>Check your plan type.</strong> You need a standalone Part D plan or a Medicare Advantage plan with drug coverage. PACE and private fee-for-service-only plans are excluded, per <a href="https://www.ncoa.org/article/expanding-access-to-weight-loss-medications-the-medicare-glp-1-bridge-program/" target="_blank" rel="noopener">NCOA</a>.</li>
<li><strong>Check whether you already have GLP-1 coverage.</strong> If Part D already covers your GLP-1 for diabetes, sleep apnea, MASH or heart disease, you stay with your regular plan, according to <a href="https://www.cms.gov/medicare/coverage/prescription-drug-coverage/medicare-glp-1-bridge/information-part-d-plans" target="_blank" rel="noopener">CMS</a>.</li>
<li><strong>Talk to your prescriber.</strong> Bring records of your BMI and any qualifying conditions from when you first started (or will start) GLP-1 therapy. Ask which covered drug fits you: Wegovy pen or pill, the Zepbound KwikPen, or Foundayo.</li>
<li><strong>Your prescriber documents and attests.</strong> The prescriber records your BMI and qualifying condition as of when therapy started and attests that you met the criteria then, per the <a href="https://www.cms.gov/files/document/medicare-glp-1-bridge-expectations-faqs.pdf" target="_blank" rel="noopener">CMS Bridge FAQ</a> and NCOA.</li>
<li><strong>Your prescriber submits to the central processor.</strong> The prescription and prior authorization request go to the Bridge's central processor. Claims sent through normal Part D channels are likely to be rejected, as <a href="https://www.forbes.com/sites/joshuacohen/2026/08/01/medicares-glp-1-bridge-program-offers-access-but-isnt-straightforward/" target="_blank" rel="noopener">Forbes reported</a>.</li>
<li><strong>Wait for a coverage decision.</strong> <a href="https://www.aarp.org/medicare/medicare-glp1-bridge-program-eligibility/" target="_blank" rel="noopener">AARP reported in September 2026</a> that determinations were taking about 12 hours. Forbes said earlier that processing could take up to several days.</li>
<li><strong>Fill at the pharmacy and pay $50.</strong> Each one-month supply (28 or 30 days, depending on the drug) costs $50, according to <a href="https://www.npr.org/2026/05/06/nx-s1-5812662/medicare-bridge-glp1-drugs-copay" target="_blank" rel="noopener">NPR</a>.</li>
</ol>
<p>If a pharmacy rejects your claim, ask whether it was sent to the Bridge processor rather than your Part D plan. Forbes flagged this routing step as a common source of rejected claims.</p>
<h3>What the $50 copay counts toward, and what it does not</h3>
<table>
<thead><tr><th>Question</th><th>Answer (as of October 2026)</th><th>Source</th></tr></thead>
<tbody>
<tr><td>Does the $50 count toward your Part D deductible?</td><td>No</td><td><a href="https://www.npr.org/2026/05/06/nx-s1-5812662/medicare-bridge-glp1-drugs-copay" target="_blank" rel="noopener">NPR</a></td></tr>
<tr><td>Does it count toward the $2,100 Part D out-of-pocket cap for 2026?</td><td>No</td><td><a href="https://www.ncoa.org/article/expanding-access-to-weight-loss-medications-the-medicare-glp-1-bridge-program/" target="_blank" rel="noopener">NCOA</a></td></tr>
<tr><td>Does Extra Help (Low-Income Subsidy) lower the $50?</td><td>No</td><td><a href="https://www.cnbc.com/2026/06/30/medicare-obesity-drug-glp-1-coverage-starting-july-1.html" target="_blank" rel="noopener">CNBC</a></td></tr>
<tr><td>Can manufacturer coupons lower the $50?</td><td>No, according to AARP</td><td><a href="https://www.aarp.org/medicare/glp1-weight-loss-copay-program/" target="_blank" rel="noopener">AARP</a></td></tr>
</tbody>
</table>
<p>The reason is structural: the Bridge operates outside the Part D benefit, so its copays live in a separate bucket, as <a href="https://www.mintz.com/insights-center/viewpoints/2146/2026-01-05-balance-model-and-new-wave-cms-drug-pricing-models" target="_blank" rel="noopener">Mintz</a> explains. In practice, budget $50 a month for the GLP-1 on top of whatever you spend on your other Part D drugs. Over a full year, 12 monthly fills at $50 come to $600.</p>
<h3>How many people have signed up</h3>
<p>About 250,000 people enrolled in the Bridge in July 2026, and enrollment topped 500,000 by the end of August, according to a White House report of August 31 cited by <a href="https://www.aarp.org/medicare/medicare-glp1-bridge-program-eligibility/" target="_blank" rel="noopener">AARP</a>. CMS Administrator Mehmet Oz put the figure at 600,000 the same day, as noted in <a href="https://thehill.com/opinion/healthcare/6121634-medicare-glp1-bridge-enrollment/" target="_blank" rel="noopener">The Hill</a>. These are government figures that have not been independently verified.</p>`,
  },
  {
    heading: "What happens to Medicare GLP-1 coverage in 2027 and beyond?",
    body: `<p>Medicare GLP-1 coverage for weight loss continues through the $50 Medicare GLP-1 Bridge until December 31, 2027, and on January 1, 2027 a Medicare negotiated price of $274 a month for semaglutide (Ozempic, Wegovy, Rybelsus) takes effect. What happens after 2027 is uncertain, because the Bridge is temporary and the Part D portion of CMS's BALANCE Model has been delayed indefinitely.</p>
<h3>What changes between 2026 and 2027</h3>
<table>
<thead><tr><th>Item</th><th>2026</th><th>2027</th><th>Source</th></tr></thead>
<tbody>
<tr><td>Medicare GLP-1 Bridge</td><td>Runs from July 1, $50 copay</td><td>Continues through Dec 31, 2027, $50 copay</td><td><a href="https://www.cms.gov/medicare/coverage/prescription-drug-coverage/medicare-glp-1-bridge" target="_blank" rel="noopener">CMS</a></td></tr>
<tr><td>Medicare price for semaglutide</td><td>$245 net under the Bridge</td><td>$274 negotiated "maximum fair price" takes effect Jan 1</td><td><a href="https://www.biopharmadive.com/news/medicare-price-negotiation-wegovy-ozempic-trelegy-2027/806526/" target="_blank" rel="noopener">BioPharma Dive</a></td></tr>
<tr><td>Part D out-of-pocket cap</td><td>$2,100</td><td>$2,400 (reported)</td><td><a href="https://www.ncoa.org/article/medicare-part-d-cost-sharing-chart" target="_blank" rel="noopener">NCOA</a>, <a href="https://seniorsite.org/resource/medicare-part-d-cap-2027" target="_blank" rel="noopener">SeniorSite</a></td></tr>
<tr><td>Maximum Part D standard deductible</td><td>$615</td><td>$700 (reported)</td><td><a href="https://www.americanseniorchoices.com/blog/part-d-out-of-pocket-cap-2027-math" target="_blank" rel="noopener">American Senior Choices</a></td></tr>
<tr><td>Wegovy and Ozempic list price</td><td>About $1,349 (Wegovy)</td><td>$675</td><td><a href="https://www.prnewswire.com/news-releases/novo-nordisk-announces-significant-reduction-in-us-list-price-for-wegovy-ozempic-and-rybelsus-semaglutide-medicines-building-on-continued-efforts-to-expand-access-302695705.html" target="_blank" rel="noopener">Novo Nordisk</a></td></tr>
<tr><td>BALANCE Model, Part D side</td><td>Planned for Jan 2027</td><td>Delayed indefinitely</td><td><a href="https://www.aha.org/news/headline/2026-04-22-cms-delays-part-d-portion-balance-model-expansion-glp-1-access" target="_blank" rel="noopener">AHA</a></td></tr>
</tbody>
</table>
<p>The 2027 Part D cap and deductible figures come from secondary sources citing CMS's CY2027 Rate Announcement of April 6, 2026; confirm them on cms.gov or in your plan's 2027 materials.</p>
<h3>What the $274 negotiated price does and does not do</h3>
<p>CMS announced on November 25, 2025 a negotiated Medicare price of $274 for a 30-day supply of semaglutide, about 71% below the 2024 list price of $959, effective January 1, 2027, according to <a href="https://www.biopharmadive.com/news/medicare-price-negotiation-wegovy-ozempic-trelegy-2027/806526/" target="_blank" rel="noopener">BioPharma Dive</a> and <a href="https://www.amcp.org/sites/default/files/2025-12/Federal%20Update_CMS%20Releases%20IPAY%202027%20Negotiated%20Prices.pdf" target="_blank" rel="noopener">AMCP</a>. It is easy to misread this number, so keep three points in mind:</p>
<ul>
<li><strong>It is what Medicare pays, not your copay.</strong> Your cost still depends on your Part D plan's tier and coverage phase, as <a href="https://247wallst.com/personal-finance/2026/08/21/medicare-negotiated-ozempic-down-to-274-for-2027-her-part-d-plan-still-sets-the-copay/" target="_blank" rel="noopener">24/7 Wall St.</a> explains.</li>
<li><strong>It does not create weight-loss coverage.</strong> Part D still excludes weight-loss-only use outside the Bridge.</li>
<li><strong>It is higher than the Bridge price.</strong> KFF has noted that $274 is above the $245 net price Novo agreed to in the November 2025 deal, and how the two interact is unresolved, as summarized by <a href="https://intuitionlabs.ai/articles/medicare-drug-price-negotiation-list" target="_blank" rel="noopener">IntuitionLabs</a>.</li>
</ul>
<p>For most people who use Ozempic for diabetes or Wegovy for a covered heart-related use in 2027, the practical effect shows up through the Part D cap. A higher $2,400 cap means your maximum out-of-pocket spending on covered Part D drugs rises compared with 2026, even as Medicare pays less per prescription.</p>
<h3>What about BALANCE?</h3>
<p>The Part D portion of CMS's BALANCE Model, which was meant to extend negotiated GLP-1 coverage through Part D plans in January 2027, was delayed indefinitely on April 21, 2026, after plans covering at least 80% of beneficiaries did not sign on, per <a href="https://www.aha.org/news/headline/2026-04-22-cms-delays-part-d-portion-balance-model-expansion-glp-1-access" target="_blank" rel="noopener">AHA News</a>.</p>
<h3>After December 31, 2027</h3>
<p>Coverage after the Bridge ends is uncertain, as <a href="https://www.cnbc.com/2026/06/30/medicare-obesity-drug-glp-1-coverage-starting-july-1.html" target="_blank" rel="noopener">CNBC</a> and <a href="https://www.kff.org/quick-insights/cms-extends-medicares-short-term-bridge-program-for-glp-1-obesity-drug-coverage/" target="_blank" rel="noopener">KFF</a> have reported. If you are on a GLP-1 through the Bridge, watch for CMS announcements during 2027 and keep a backup plan in mind, such as the manufacturers' self-pay prices. Review your Part D options during each fall open enrollment period, too.</p>`,
  },
  {
    heading: "Does Medicaid cover GLP-1s for weight loss?",
    body: `<p>Medicaid coverage of GLP-1s for weight loss depends on your state: KFF counted 13 state Medicaid programs covering GLP-1s for obesity under fee-for-service as of January 2026, down from 16 in October 2025. Medicaid generally covers GLP-1s for type 2 diabetes in every state.</p>
<p>Each state decides whether its Medicaid program covers GLP-1s for obesity, and coverage remains limited because of cost, according to <a href="https://www.kff.org/medicaid/medicaid-coverage-of-and-spending-on-glp-1s/" target="_blank" rel="noopener">KFF</a>. Where obesity coverage exists, your copay is set by the state within low federal limits, per <a href="https://brevy.com/medicaid/cost-sharing-copays" target="_blank" rel="noopener">Brevy's summary of federal rules</a>, so it is usually far below any self-pay price.</p>
<h3>States covering GLP-1s for obesity (KFF, January 2026)</h3>
<table>
<thead><tr><th>Status as of January 2026</th><th>States</th></tr></thead>
<tbody>
<tr><td>Covering under fee-for-service (13)</td><td>Delaware, Kansas, Massachusetts, Michigan, Minnesota, Mississippi, Missouri, North Carolina, Rhode Island, Tennessee, Utah, Virginia, Wisconsin</td></tr>
<tr><td>Ended coverage January 1, 2026</td><td>California, New Hampshire, Pennsylvania, South Carolina</td></tr>
<tr><td>Dropped and then reinstated</td><td>North Carolina (dropped October 2025, reinstated December 2025)</td></tr>
</tbody>
</table>
<p>Sources: <a href="https://www.kff.org/medicaid/medicaid-coverage-of-and-spending-on-glp-1s/" target="_blank" rel="noopener">KFF</a>; <a href="https://stateline.org/2025/11/28/states-retreat-from-covering-drugs-for-weight-loss/" target="_blank" rel="noopener">Stateline</a>.</p>
<h3>Why states are pulling back</h3>
<p>Cost is the main driver. California's Medi-Cal ended coverage of GLP-1s for weight loss effective January 1, 2026, to cut pharmacy spending, according to <a href="https://www.kff.org/medicaid/medicaid-coverage-of-and-spending-on-glp-1s/" target="_blank" rel="noopener">KFF</a> and <a href="https://stateline.org/2025/11/28/states-retreat-from-covering-drugs-for-weight-loss/" target="_blank" rel="noopener">Stateline</a>. The pressure has continued in 2026: Rhode Island's governor proposed removing weight-loss GLP-1 coverage from Medicaid, and more states were considering cuts, <a href="https://stateline.org/2026/04/30/more-states-consider-dropping-glp-1-weight-loss-drugs-from-medicaid/" target="_blank" rel="noopener">Stateline reported in April 2026</a>. The list above may have changed since January, so treat it as a starting point rather than a final answer.</p>
<h3>Could the federal deal or BALANCE help Medicaid enrollees?</h3>
<p>The November 2025 deal set a $245 monthly price for covered GLP-1s in participating Medicaid programs, according to <a href="https://www.ajmc.com/view/trump-announces-deals-with-eli-lilly-novo-nordisk-for-lower-weight-loss-drug-prices" target="_blank" rel="noopener">AJMC</a>. CMS's BALANCE Model is the vehicle for that in Medicaid. States could choose a BALANCE start date between May 1, 2026 and January 1, 2027, and CMS accepted applications through July 31, 2026, according to <a href="https://www.kff.org/medicare/what-to-know-about-the-balance-model-for-glp-1s-in-medicare-and-medicaid/" target="_blank" rel="noopener">KFF</a>, which lists the Medicaid model as running through December 2031. Prices are negotiated and kept confidential through supplemental rebate agreements, per <a href="https://www.mintz.com/insights-center/viewpoints/2146/2026-01-05-balance-model-and-new-wave-cms-drug-pricing-models" target="_blank" rel="noopener">Mintz</a>.</p>
<p>As of mid to late 2026, CMS had not publicly named any participating BALANCE Medicaid states, according to <a href="https://www.medicaldaily.com/balance-model-medicaid-glp1-state-participation-coverage-gap-477723" target="_blank" rel="noopener">Medical Daily</a>. That means you cannot yet assume your state will add coverage through BALANCE. Check the CMS BALANCE page and your state Medicaid agency for updates.</p>
<h3>What to do if you have Medicaid</h3>
<ol>
<li><strong>Check your state's current policy.</strong> Call the member services number on your Medicaid card, or ask your managed care plan, whether GLP-1s are covered for obesity and what prior authorization requires.</li>
<li><strong>Ask about other covered uses.</strong> If you have type 2 diabetes, a GLP-1 is generally covered for that purpose in every state, per <a href="https://www.kff.org/medicaid/medicaid-coverage-of-and-spending-on-glp-1s/" target="_blank" rel="noopener">KFF</a>. Your clinician can tell you whether another approved use applies to you.</li>
<li><strong>Know the savings card rule.</strong> Manufacturer savings cards cannot be used with Medicaid, according to <a href="https://www.novocare.com/patient/medicines/wegovy/savings-offer.html" target="_blank" rel="noopener">NovoCare</a>.</li>
<li><strong>Compare the cash route.</strong> If your state does not cover obesity treatment, the lowest self-pay prices start at $149 a month for pill starting doses as of October 2026, based on <a href="https://www.cnn.com/2026/01/06/health/wegovy-pill-weight-loss-explained" target="_blank" rel="noopener">CNN</a> and <a href="https://www.lilly.com/lillydirect/foundayo" target="_blank" rel="noopener">LillyDirect</a>. Talk with your clinician before choosing.</li>
</ol>`,
  },
];
